<?php
if (!defined('ABSPATH')) { exit; }
get_header();
$materials = ['NBR', 'FKM', 'EPDM', 'Silicone']; $hardness = ['60 ShA', '70 ShA', '80 ShA', '90 ShA']; $colors = [['id'=>'black','label'=>'Black','hex'=>'#000'],['id'=>'red','label'=>'Red','hex'=>'#c62828'],['id'=>'green','label'=>'Green','hex'=>'#2e7d32'],['id'=>'blue','label'=>'Blue','hex'=>'#1565c0'],['id'=>'clear','label'=>'Translucent','hex'=>'#e0e0e0']];
$selected_material = sanitize_text_field(wp_unslash($_GET['material'] ?? '')); $selected_hardness = sanitize_text_field(wp_unslash($_GET['hardness'] ?? '')); $selected_color = sanitize_key(wp_unslash($_GET['color'] ?? '')); $sort = sanitize_key(wp_unslash($_GET['sort'] ?? 'relevance'));
$query_args = ['post_type'=>'oubei_product','post_status'=>'publish','posts_per_page'=>3,'paged'=>max(1,get_query_var('paged'))]; if ($selected_material) $query_args['meta_query'] = [['key'=>'_oubei_material','value'=>$selected_material,'compare'=>'LIKE']]; if ($sort === 'name') { $query_args['orderby']='title'; $query_args['order']='ASC'; }
$catalog = new WP_Query($query_args);
?>
<main class="oubei-catalog-page"><div class="oubei-container"><nav class="oubei-breadcrumbs"><a href="<?php echo esc_url(home_url('/')); ?>">Home</a><span>›</span><span>Products</span><span>›</span><strong>O-Rings &amp; Sealing Solutions</strong></nav><div class="oubei-mobile-catalog-title"><h1>Precision O-Rings</h1><button class="oubei-filter-toggle" type="button" data-filter-toggle aria-expanded="false">☷ Filters</button></div><div class="oubei-catalog-layout"><aside id="catalog-filters" class="oubei-catalog-filters"><div class="oubei-filter-panel"><div class="oubei-filter-head"><h2>Filters</h2><a href="<?php echo esc_url(get_post_type_archive_link('oubei_product')); ?>">Clear all</a></div><form id="catalog-filter-form" method="get"><fieldset><legend>Material</legend><?php foreach($materials as $material): ?><label><input type="checkbox" name="material" value="<?php echo esc_attr($material); ?>" <?php checked($selected_material,$material); ?>><span><?php echo esc_html($material === 'NBR' ? 'NBR (Nitrile)' : ($material === 'FKM' ? 'FKM (Viton)' : $material)); ?></span></label><?php endforeach; ?></fieldset><fieldset><legend>Hardness (Shore A)</legend><div class="oubei-hardness-grid"><?php foreach($hardness as $value): ?><button type="submit" name="hardness" value="<?php echo esc_attr($value); ?>" class="<?php echo $selected_hardness === $value ? 'is-selected' : ''; ?>"><?php echo esc_html($value); ?></button><?php endforeach; ?></div></fieldset><fieldset><legend>Color</legend><div class="oubei-color-grid"><?php foreach($colors as $color): ?><button type="submit" name="color" value="<?php echo esc_attr($color['id']); ?>" aria-label="Filter by <?php echo esc_attr($color['label']); ?>" class="<?php echo $selected_color === $color['id'] ? 'is-selected' : ''; ?>"><span style="background:<?php echo esc_attr($color['hex']); ?>"></span></button><?php endforeach; ?></div></fieldset></form></div><div class="oubei-cert-card"><div class="oubei-cert-icon">✓</div><h2>ISO Certified</h2><p>All products undergo 100% optical inspection and material batch testing.</p></div></aside><section class="oubei-catalog-results"><div class="oubei-catalog-toolbar"><h1>Precision O-Rings</h1><label><span>Sort by:</span><select form="catalog-filter-form" onchange="this.form.submit()" name="sort"><option value="relevance" <?php selected($sort,'relevance'); ?>>Relevance</option><option value="name" <?php selected($sort,'name'); ?>>Name (A-Z)</option></select></label></div><?php if($catalog->have_posts()): ?><div class="oubei-catalog-grid"><?php while($catalog->have_posts()): $catalog->the_post(); $product = oubei_get_product_data(get_the_ID()); $slot = oubei_get_media_slot('products.' . ($product['slug'] ?? '')); ?><article class="oubei-catalog-card"><a class="oubei-catalog-image" href="<?php the_permalink(); ?>"><img src="<?php echo esc_url($slot['url']); ?>" alt="<?php echo esc_attr($slot['alt']); ?>"></a><div class="oubei-catalog-card-body"><h2><a href="<?php the_permalink(); ?>"><?php echo esc_html($product['name']); ?></a></h2><p><?php echo esc_html($product['short_description']); ?></p><div><span class="oubei-card-label"><?php echo esc_html($product['code']); ?></span><a class="oubei-inquire-link" href="<?php echo esc_url(home_url('/quote')); ?>">✉ Inquire Now</a></div></div></article><?php endwhile; wp_reset_postdata(); ?></div><?php else: ?><div class="oubei-empty-state"><p>No products match these filters.</p><a href="<?php echo esc_url(get_post_type_archive_link('oubei_product')); ?>">Clear filters and view all products</a></div><?php endif; ?><nav class="oubei-pagination" aria-label="Catalog pagination"><?php echo wp_kses_post(paginate_links(['total'=>$catalog->max_num_pages,'current'=>max(1,get_query_var('paged')),'type'=>'list'])); ?></nav></section></div></div></main><?php get_footer();
